{
  "name": "Weiss SB 22 气候试验箱",
  "name_en": "Weiss SB 22 climate chamber",
  "manufacturer": "Weiss",
  "description": "用于控制和读取 Weiss SB 22 气候试验箱的温度、湿度及数字通道状态。该设备通过 RS-232 串口通信，适合环境模拟、样品老化与温湿度稳定性测试。",
  "description_en": "Controls and reads temperature, humidity, and digital channel states of a Weiss SB 22 climate chamber. The device communicates via RS-232 serial interface and is used for environmental simulation, sample aging, and temperature/humidity stability testing.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化气候试验箱通信。",
      "description_en": "Initialize communication with the climate chamber."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-get_temperature_target",
      "description": "获取温度设定值。",
      "description_en": "Get the target temperature setpoint."
    },
    {
      "action_name": "auto-get_humidity",
      "description": "获取当前湿度。",
      "description_en": "Get the current humidity."
    },
    {
      "action_name": "auto-get_humidity_target",
      "description": "获取湿度设定值。",
      "description_en": "Get the target humidity setpoint."
    },
    {
      "action_name": "auto-get_digital_ch",
      "description": "获取数字通道状态。",
      "description_en": "Get the digital channel state."
    },
    {
      "action_name": "auto-set_digital_ch",
      "description": "设置数字通道状态。",
      "description_en": "Set the digital channel state."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度设定值。",
      "description_en": "Set the temperature setpoint."
    },
    {
      "action_name": "auto-set_humidity",
      "description": "设置湿度设定值。",
      "description_en": "Set the humidity setpoint."
    },
    {
      "action_name": "auto-write",
      "description": "向设备写入串口协议命令。",
      "description_en": "Write a serial protocol command to the device."
    },
    {
      "action_name": "auto-read",
      "description": "从设备读取串口响应。",
      "description_en": "Read the serial response from the device."
    },
    {
      "action_name": "auto-check_for_errors",
      "description": "检查设备响应中的错误状态。",
      "description_en": "Check the device response for error conditions."
    }
  ],
  "tag_hints": [
    "climate chamber",
    "environmental testing",
    "temperature control",
    "humidity control",
    "RS-232 serial communication",
    "environment simulation",
    "sample aging test"
  ]
}

